(function(){
  var pages={"/fassaadi-varvimine-tallinn-eramu":"facade","/katuse-pesu-ja-hooldus-tallinn":"roof","/parketi-paigaldus-tallinn-korter":"floor","/led-valgustuse-paigaldus-tallinn":"led","/vannitoa-plaatimine-tallinn":"bath"};
  function pathKey(){return location.pathname.replace(/\.html$/,'').replace(/\/$/,'')||'/'}
  function addCaseStudyCss(){
    if(document.getElementById('case-study-layout-copy-fix'))return;
    var style=document.createElement('style');
    style.id='case-study-layout-copy-fix';
    style.textContent='.skip-link{display:none!important;visibility:hidden!important}.case-study-page .case-study-layout>.center-image{display:block;margin:0 auto 2rem;max-width:min(100%,980px)}.case-study-page .case-study-layout>.center-image img{display:block;width:100%;max-width:100%;max-height:68vh;height:auto;object-fit:contain}.case-study-page .geo-project-context{padding:3.25em 0}.case-study-page .geo-project-context .inner{max-width:980px}@media screen and (max-width:736px){.case-study-page article#main>header{padding:5.5em 1.5em 2.5em}.case-study-page article#main>header h1{font-size:1.45em;line-height:1.35}.case-study-page article#main>header p{font-size:.9em;line-height:1.55}.case-study-page .wrapper.style5{padding:2.35em 0}.case-study-page .wrapper.style5>.inner{width:100%;padding:0 1.25em}.case-study-page .geo-project-context{padding:2.2em 0}.case-study-page .case-study-layout>.center-image{margin-bottom:1.5em;max-width:100%}.case-study-page .case-study-layout>.center-image img{max-height:38vh}.case-study-page .center-image figcaption{font-size:.78em;margin-top:.6rem}}@media screen and (max-width:480px){.case-study-page .case-study-layout>.center-image img{max-height:34vh}}';
    document.head.appendChild(style);
  }
  function syncCaseStudyMenu(){
    var menu=document.getElementById('menu');
    if(!menu||menu.querySelector('.submenu'))return;
    var list=menu.querySelector('ul');
    if(!list)return;
    list.innerHTML='<li><a href="index.html">Avaleht</a></li><li class="submenu open"><div class="submenu-header"><span>Teenused</span><span class="submenu-arrow">&#9662;</span></div><ul class="submenu-items"><li><a href="plaatimine.html">Plaatimine</a></li><li><a href="maalritood.html">Maalritööd</a></li><li><a href="ledlahendused.html">LED lahendused</a></li><li><a href="seinapaneelidepaigaldus.html">Seinapaneelide paigaldus</a></li><li><a href="parketipaigaldus.html">Parketi paigaldus</a></li><li><a href="tapeetimine.html">Tapeetimine</a></li><li><a href="kipsitood.html">Kipsitööd</a></li><li><a href="lammutustood.html">Lammutustööd</a></li><li><a href="tellingutepaigaldus.html">Tellingute paigaldus</a></li><li><a href="betoonitood.html">Betoonitööd</a></li><li><a href="vundamenditood.html">Vundamenditööd</a></li><li><a href="fassaaditood.html">Fassaaditööd</a></li><li><a href="katusetood.html">Katusetööd</a></li><li><a href="lumetood.html">Lumetööd</a></li></ul></li><li><a href="hinnakiri.html">Hinnakiri</a></li><li><a href="tehtudtood.html">Tehtud tööd</a></li><li><a href="kontakt.html">Kontakt</a></li>';
  }
  function sectionParagraphs(heading){
    var heads=document.querySelectorAll('h2');
    for(var h=0;h<heads.length;h++){
      if(heads[h].textContent.trim()===heading){
        var out=[],n=heads[h].nextElementSibling;
        while(n&&n.tagName&&n.tagName.toLowerCase()==='p'){out.push(n);n=n.nextElementSibling;}
        return out;
      }
    }
    return null;
  }
  function setSection(heading, htmls){
    var ps=sectionParagraphs(heading);
    if(!ps)return;
    for(var i=0;i<htmls.length&&i<ps.length;i++)if(htmls[i])ps[i].innerHTML=htmls[i];
  }
  function setGeo(html){var p=document.querySelector('.geo-entity-summary');if(p)p.innerHTML=html;}
  function refineCopy(kind){
    var data={
      facade:{
        geo:'<strong>RK Meistrid OÜ</strong> teeb fassaadi värvimise ja muid renoveerimistöid Tallinnas ning Harjumaal. Selle näite kaudu saab hinnata, kuidas planeerime puitfassaadi puhastuse, parandused, kruntimise, värvimise ja ligipääsu enne töö alustamist.',
        why:['Fassaadi värvimisel mõjutab lõpptulemust kõige rohkem eeltöö kvaliteet. Selline tehtud töö näide aitab kliendil aru saada, miks pind tuleb enne värvimist puhastada, kontrollida ja vajadusel parandada, mitte katta probleemseid kohti uue värvikihiga.'],
        offer:[null,'See projektileht näitab konkreetset fassaadi värvimise kogemust. Üldise teenuse, hinnastamise ja tööde valiku kohta on põhileht <a href="fassaadivarvimine.html">fassaadi värvimine</a> ning laiem ülevaade lehel <a href="fassaaditood.html">fassaaditööd</a>. Nii on kliendil lihtne eristada, milline info puudutab tehtud objekti ja milline kirjeldab tellitavat teenust.'],
        image:['Foto aitab hinnata fassaadi seisukorda, töö iseloomu ja lõpptulemust. Pilt on lisatud selleks, et klient näeks päris objekti, mitte üldist illustratsiooni, ning saaks võrrelda seda oma maja või kavandatava tööga.']
      },
      roof:{
        geo:'<strong>RK Meistrid OÜ</strong> teeb katuse hoolduse, pesu ja seotud renoveerimistöid Tallinnas ning Harjumaal. See näide selgitab, kuidas hindame katuse seisukorda, puhastame katusepinda ja vaatame üle kohad, mis võivad hiljem vajada parandust.',
        why:['Katuse hoolduses on oluline märgata väikeseid probleeme enne, kui neist saab suurem remont. Selline tehtud töö näide aitab kliendil aru saada, miks pesu, rennide kontroll, läbiviikude ülevaatus ja ohutu ligipääs kuuluvad sama töö planeerimise juurde.'],
        offer:[null,'See leht kirjeldab konkreetset tehtud tööd. Üldise teenuse jaoks on tähtsamad lehed <a href="katusetood.html">katusetööd</a> ja hooajalise ohutuse vaatest ka <a href="lumetood.html">lumetööd</a>. Nii saab klient eraldi vaadata päris töö näidet ning seejärel liikuda edasi teenuse kirjelduse või hinnapäringu juurde.'],
        image:['Katuse foto näitab töö tegelikku olukorda ja aitab hinnata, millise mustuse, sambla või ligipääsuga võib sarnasel objektil arvestada. Pildi eesmärk on anda kliendile realistlik ettekujutus hooldustöö mahust ja võimalikest riskikohtadest.']
      },
      floor:{
        geo:'<strong>RK Meistrid OÜ</strong> teeb parketi ja laminaatpõrandate paigaldust Tallinnas ning Harjumaal. See näide kirjeldab korteri põrandatööd praktilisest vaatest: aluspinna kontrolli, paigalduse suunda, paisumisvuuke, liiste ja lõpptulemuse ülevaatust.',
        search:['Põhiteenus asub lehel <a href="parketipaigaldus.html">parketi paigaldus Tallinnas ja Harjumaal</a>. Seal on üldine teenuse kirjeldus, tööprotsess ja hinnastamise loogika. See leht keskendub ühele tehtud tööle, et klient näeks, kuidas parketi paigaldus korteris päriselt planeeritakse ja millised detailid mõjutavad lõpptulemust.','Selline jaotus vähendab kordusi ning teeb info selgemaks. Teenuseleht vastab küsimusele, mida saab tellida. Tehtud töö leht näitab, kuidas üks korteri põrand lahendati, milliste piirangutega arvestati ja millist infot võiks klient sarnase töö pakkumiseks saata.'],
        result:[null,'Foto ja kirjeldus aitavad siduda töö tulemuse praktiliste detailidega: aluspind, paigaldus, liistud, üleminekud ja korteri kasutusmugavus. Nii saab klient hinnata, kas näide sarnaneb tema objektile ja milliseid küsimusi enne hinnapäringut täpsustada.']
      },
      led:{
        geo:'<strong>RK Meistrid OÜ</strong> paigaldab LED-valgustust ja kaudvalguse lahendusi Tallinnas ning Harjumaal. Selle näite kaudu saab vaadata, kuidas planeerime valguse eesmärgi, profiilid, kaabelduse, toiteploki asukoha ja lõppviimistluse.',
        why:['LED lahenduse puhul määrab töökindluse planeerimine enne viimistlust. Selline tehtud töö näide aitab kliendil näha, miks valguse suund, profiili valik, toiteploki ligipääs ja kaablite peitmine tuleb enne paigaldust läbi mõelda.'],
        offer:[null,'See projektileht on konkreetne tehtud töö näide. Laiem teenuse ülevaade on lehel <a href="ledlahendused.html">LED lahendused</a>. Kui LED paigaldus on seotud uue kipslae, seinapaneelide või siseviimistlusega, võivad vajalikud olla ka <a href="kipsitood.html">kipsitööd</a> ja <a href="seinapaneelidepaigaldus.html">seinapaneelide paigaldus</a>. Need seosed aitavad tööjärjekorra juba päringu alguses selgemaks teha.'],
        image:['Foto aitab näha, millise valgusjoone ja viimistlusega on tegemist. LED lahenduse puhul on visuaalne tulemus sama oluline kui tehniline pool: profiil, hajuti, ühendused ja hooldatavus peavad töötama koos.']
      },
      bath:{
        geo:'<strong>RK Meistrid OÜ</strong> teeb vannitoa plaatimist ja märgruumide viimistlust Tallinnas ning Harjumaal. See näide selgitab, kuidas planeerime aluspinna ettevalmistuse, hüdroisolatsiooni, kallete kontrolli, plaatimise, vuukimise ja silikoonimise.',
        why:['Märgruumis sõltub tulemus eelkõige õigesti tehtud ettevalmistusest. Selline töö näide aitab kliendil aru saada, miks hüdroisolatsioon, kalded, äravoolu ümbrus ja vuukide viimistlus on sama tähtsad kui nähtav plaat ise.'],
        offer:[null,'See projektileht on konkreetne tehtud töö näide. Laiem teenuse ja hinnastamise ülevaade on lehel <a href="plaatimine.html">plaatimine</a>. Kui vannitoa töö vajab lisaks aluspinna ehitamist, on seotud ka <a href="kipsitood.html">kipsitööd</a>, <a href="lammutustood.html">lammutustööd</a> ja vajadusel <a href="maalritood.html">maalritööd</a>. Nii saab klient paremini aru, millised etapid võivad ühe vannitoa töö juurde kuuluda.'],
        image:['Foto aitab hinnata plaatimise stiili, vuukide üldmuljet ja märgruumi lõpptulemust. Päris töö näide annab kliendile parema ettekujutuse sellest, millist täpsust ja tööjärjekorda sarnane vannitoa renoveerimine vajab.']
      }
    }[kind];
    if(!data)return;
    if(data.geo)setGeo(data.geo);
    if(data.why)setSection('Miks see on oluline?',data.why);
    if(data.offer)setSection('Mida klient sarnase töö pakkumiseks saata võiks?',data.offer);
    if(data.image)setSection('Pildi ja töö seos',data.image);
    if(data.search)setSection('Miks see töö on otsingus eraldi leht?',data.search);
    if(data.result)setSection('Tulemuse hindamine',data.result);
  }
  function applyFix(){var kind=pages[pathKey()];if(!kind)return;addCaseStudyCss();syncCaseStudyMenu();refineCopy(kind)}
  if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',applyFix);else applyFix();
})();
